  font-weight: 700;
  min-width: 20px;
  padding: 0 3px;
  border-radius: 4px;
  border-width: 1px;
  top: 2px;
  left: 2px;
}
/* 當時段有容量徽章時，讓第一張課程卡的學生姓名向右讓位，避免遮擋 */
.slot:has(.capacity-badge) .course-block:first-of-type .cb-student {
  padding-left: 30px;
}
.slot:has(.capacity-badge-compact) .course-block:first-of-type .cb-student {
  padding-left: 24px;
}

