@media (max-width: 768px) {
  .capacity-badge {
    font-size: 0;
    min-width: 8px;
    width: 8px;
    height: 8px;
    padding: 0;
    border-radius: 50%;
  }
}

input.new_string:
@media (max-width: 768px) {
  .capacity-badge {
    font-size: 8px;
    min-width: 18px;
    padding: 0 2px;
    border-radius: 3px;
    border-width: 1px;
  }
}

input.old_string:
