}

input.old_string:
/* 緊湊模式的角標（到班/漏點/請假/未填評量）：字更小、邊距更緊，讓 split 卡片有更多姓名空間 */
.teacher-grid.teacher-grid-compact .rc-tag {
  font-size: 8px;
  padding: 0 2px;
