  padding: 0 2px;
  right: 2px;
}
/* 修正：第二個角標（rc-tag-second）須維持在底部，避免特異性衝突讓 top/bottom 同時生效而縱向撐開 */
.teacher-grid.teacher-grid-compact .rc-tag.rc-tag-second {
  top: auto;
  bottom: 2px;
}

